//! Shard transfer measurement tool (Phase 0 task 0.4).
//!
//! Compares two transports for moving shards between a gateway and a
//! storage node, under identical conditions:
//!
//! - `grpc`: tonic/gRPC over HTTP/2 using the real `arca_lake.storage.v1`
//!   service (client-streaming `PutShard`, server-streaming `GetShard`).
//! - `raw`: length-prefixed frames over a TCP connection, one logical
//!   request at a time per connection.
//!
//! Both can run with TLS (rustls, self-signed certificate generated by the
//! server). The server computes CRC-32C over every received shard, as the
//! storage engine would. Each role prints one JSON line with throughput,
//! latency percentiles, CPU time, and peak RSS so that a driver script can
//! build a table. Numbers are only meaningful relative to each other on the
//! same machine; see `benchmarks/README.md`.
//!
//! Backpressure: both transports are flow controlled end to end (TCP
//! windows; HTTP/2 stream and connection windows for gRPC). The `--server-delay-us`
//! option makes the server slow so that the client's behaviour under
//! backpressure (bounded memory) can be observed.

#![allow(
    clippy::cast_precision_loss,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_lossless, // rusage field types differ between Linux and macOS
    clippy::too_many_lines,
    clippy::struct_excessive_bools
)]

use std::net::SocketAddr;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use arca_lake_protocol::storage::v1 as pb;
use bytes::Bytes;
use clap::{Parser, Subcommand, ValueEnum};
use rustls::pki_types::pem::PemObject as _;
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio_stream::StreamExt;
use tokio_stream::wrappers::ReceiverStream;
use tonic::transport::{Certificate, Channel, ClientTlsConfig, Identity, Server, ServerTlsConfig};

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum Transport {
    Grpc,
    Raw,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum Op {
    Put,
    Get,
}

#[derive(Debug, Parser)]
#[command(
    name = "transfer-bench",
    about = "arca-lake shard transfer measurements"
)]
struct Cli {
    #[command(subcommand)]
    role: Role,
}

#[derive(Debug, Subcommand)]
enum Role {
    /// Run a server that answers PutShard/GetShard, prints stats, and exits
    /// after `--duration` seconds.
    Server(ServerArgs),
    /// Run clients against a server for `--duration` seconds and print stats.
    Client(ClientArgs),
}

#[derive(Debug, clap::Args)]
struct ServerArgs {
    #[arg(long, value_enum)]
    transport: Transport,
    #[arg(long, default_value = "127.0.0.1:0")]
    listen: SocketAddr,
    /// Enable TLS with a self-signed certificate written to `--cert-out`.
    #[arg(long)]
    tls: bool,
    #[arg(long, default_value = "/tmp/arca-transfer-bench-cert.pem")]
    cert_out: String,
    /// Write the bound address here so a driver can find the port.
    #[arg(long, default_value = "/tmp/arca-transfer-bench-addr")]
    addr_out: String,
    #[arg(long, default_value_t = 10)]
    duration: u64,
    /// Frame size for streaming responses.
    #[arg(long, default_value_t = 64 * 1024)]
    frame_bytes: usize,
    /// Artificial per-frame processing delay to create backpressure.
    #[arg(long, default_value_t = 0)]
    server_delay_us: u64,
    /// Worker threads.
    #[arg(long, default_value_t = 4)]
    threads: usize,
}

#[derive(Debug, clap::Args)]
struct ClientArgs {
    #[arg(long, value_enum)]
    transport: Transport,
    #[arg(long)]
    addr: SocketAddr,
    #[arg(long)]
    tls: bool,
    #[arg(long, default_value = "/tmp/arca-transfer-bench-cert.pem")]
    ca_cert: String,
    #[arg(long, value_enum)]
    op: Op,
    /// Shard size per request.
    #[arg(long, default_value_t = 1024 * 1024)]
    shard_bytes: usize,
    /// Frame size for streaming requests.
    #[arg(long, default_value_t = 64 * 1024)]
    frame_bytes: usize,
    /// Concurrent streams (connections for raw, streams on one channel for
    /// gRPC unless `--connections` is set).
    #[arg(long, default_value_t = 1)]
    concurrency: usize,
    /// Number of gRPC channels to spread streams over (default: 1).
    #[arg(long, default_value_t = 1)]
    connections: usize,
    #[arg(long, default_value_t = 5)]
    duration: u64,
    #[arg(long, default_value_t = 4)]
    threads: usize,
    /// Label copied into the output line.
    #[arg(long, default_value = "")]
    label: String,
}

fn main() {
    rustls::crypto::ring::default_provider()
        .install_default()
        .ok();
    let cli = Cli::parse();
    match cli.role {
        Role::Server(a) => {
            let rt = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(a.threads)
                .enable_all()
                .build()
                .unwrap();
            rt.block_on(run_server(a));
        }
        Role::Client(a) => {
            let rt = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(a.threads)
                .enable_all()
                .build()
                .unwrap();
            rt.block_on(run_client(a));
        }
    }
}

// ---------------------------------------------------------------- stats

#[derive(Debug, Default, serde::Serialize)]
struct Stats {
    role: &'static str,
    label: String,
    transport: String,
    tls: bool,
    op: String,
    shard_bytes: usize,
    frame_bytes: usize,
    concurrency: usize,
    seconds: f64,
    requests: u64,
    bytes: u64,
    throughput_mib_s: f64,
    latency_p50_ms: f64,
    latency_p99_ms: f64,
    cpu_user_s: f64,
    cpu_sys_s: f64,
    /// (user + sys) / wall, in percent of one core.
    cpu_percent: f64,
    /// Peak resident set size in bytes (platform `ru_maxrss` normalized).
    max_rss_bytes: u64,
}

fn rusage() -> (f64, f64, u64) {
    let mut ru = std::mem::MaybeUninit::<libc::rusage>::uninit();
    // SAFETY: getrusage fills the struct for the calling process; the
    // pointer is valid and RUSAGE_SELF is a valid selector.
    #[allow(unsafe_code)]
    let ru = unsafe {
        libc::getrusage(libc::RUSAGE_SELF, ru.as_mut_ptr());
        ru.assume_init()
    };
    let user = ru.ru_utime.tv_sec as f64 + ru.ru_utime.tv_usec as f64 / 1e6;
    let sys = ru.ru_stime.tv_sec as f64 + ru.ru_stime.tv_usec as f64 / 1e6;
    // Linux reports kilobytes, macOS reports bytes.
    let rss = if cfg!(target_os = "macos") {
        ru.ru_maxrss as u64
    } else {
        ru.ru_maxrss as u64 * 1024
    };
    (user, sys, rss)
}

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return 0.0;
    }
    let idx = ((sorted.len() as f64 - 1.0) * p).round() as usize;
    sorted[idx.min(sorted.len() - 1)]
}

// ---------------------------------------------------------------- TLS

fn make_cert() -> (String, String) {
    let cert = rcgen::generate_simple_self_signed(vec!["localhost".into()]).expect("generate cert");
    (cert.cert.pem(), cert.signing_key.serialize_pem())
}

fn server_tls_acceptor(cert_pem: &str, key_pem: &str) -> tokio_rustls::TlsAcceptor {
    let certs = rustls_pemfile_certs(cert_pem);
    let key = rustls_pemfile_key(key_pem);
    let cfg = rustls::ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(certs, key)
        .unwrap();
    tokio_rustls::TlsAcceptor::from(Arc::new(cfg))
}

fn client_tls_connector(ca_pem: &str) -> tokio_rustls::TlsConnector {
    let mut roots = rustls::RootCertStore::empty();
    for c in rustls_pemfile_certs(ca_pem) {
        roots.add(c).unwrap();
    }
    let cfg = rustls::ClientConfig::builder()
        .with_root_certificates(roots)
        .with_no_client_auth();
    tokio_rustls::TlsConnector::from(Arc::new(cfg))
}

fn rustls_pemfile_certs(pem: &str) -> Vec<rustls::pki_types::CertificateDer<'static>> {
    rustls::pki_types::CertificateDer::pem_slice_iter(pem.as_bytes())
        .map(|c| c.unwrap())
        .collect()
}

fn rustls_pemfile_key(pem: &str) -> rustls::pki_types::PrivateKeyDer<'static> {
    rustls::pki_types::PrivateKeyDer::from_pem_slice(pem.as_bytes()).unwrap()
}

// ---------------------------------------------------------------- raw framing
//
// Every complete message is followed by `flush()`. Plaintext TCP does not
// need it, but a TLS stream buffers encrypted bytes until flushed, and a
// request whose tail stays in that buffer deadlocks both sides (observed in
// Phase 0: random hangs with raw+TLS at concurrency >= 4). gRPC/hyper
// handle this internally; a hand-written protocol has to remember it.

const F_PUT_HDR: u8 = 1;
const F_DATA: u8 = 2;
const F_PUT_END: u8 = 3;
const F_PUT_ACK: u8 = 4;
const F_GET_REQ: u8 = 5;
const F_GET_END: u8 = 7;

async fn write_frame<W: AsyncWrite + Unpin>(
    w: &mut W,
    ty: u8,
    payload: &[u8],
) -> std::io::Result<()> {
    let mut hdr = [0u8; 5];
    hdr[..4].copy_from_slice(&(payload.len() as u32).to_le_bytes());
    hdr[4] = ty;
    w.write_all(&hdr).await?;
    if !payload.is_empty() {
        w.write_all(payload).await?;
    }
    Ok(())
}

async fn read_frame<R: AsyncRead + Unpin>(r: &mut R, buf: &mut Vec<u8>) -> std::io::Result<u8> {
    let mut hdr = [0u8; 5];
    r.read_exact(&mut hdr).await?;
    let len = u32::from_le_bytes([hdr[0], hdr[1], hdr[2], hdr[3]]) as usize;
    buf.clear();
    buf.resize(len, 0);
    if len > 0 {
        r.read_exact(buf).await?;
    }
    Ok(hdr[4])
}

// ---------------------------------------------------------------- server

#[derive(Clone)]
struct ServerShared {
    requests: Arc<AtomicU64>,
    bytes: Arc<AtomicU64>,
    frame_bytes: usize,
    delay: Duration,
    payload: Bytes,
}

async fn run_server(a: ServerArgs) {
    let shared = ServerShared {
        requests: Arc::new(AtomicU64::new(0)),
        bytes: Arc::new(AtomicU64::new(0)),
        frame_bytes: a.frame_bytes,
        delay: Duration::from_micros(a.server_delay_us),
        payload: Bytes::from(vec![0x5Au8; a.frame_bytes]),
    };
    let (cert_pem, key_pem) = make_cert();
    if a.tls {
        tokio::fs::write(&a.cert_out, &cert_pem).await.unwrap();
    }
    let listener = TcpListener::bind(a.listen).await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::fs::write(&a.addr_out, addr.to_string())
        .await
        .unwrap();
    eprintln!(
        "server listening on {addr} ({:?}, tls={})",
        a.transport, a.tls
    );

    let start = Instant::now();
    let deadline = tokio::time::sleep(Duration::from_secs(a.duration));
    tokio::pin!(deadline);

    match a.transport {
        Transport::Grpc => {
            let svc = pb::storage_node_server::StorageNodeServer::new(GrpcServer {
                shared: shared.clone(),
            })
            .max_decoding_message_size(64 << 20);
            // The same HTTP/2 windows and socket options as the storage
            // node, so that the matrix measures the stack the gateway uses.
            let mut builder = Server::builder()
                .initial_stream_window_size(Some(arca_lake_protocol::client::STREAM_WINDOW))
                .initial_connection_window_size(Some(
                    arca_lake_protocol::client::CONNECTION_WINDOW,
                ));
            if a.tls {
                let identity = Identity::from_pem(cert_pem.as_bytes(), key_pem.as_bytes());
                builder = builder
                    .tls_config(ServerTlsConfig::new().identity(identity))
                    .unwrap();
            }
            // As in the storage node: tonic does not apply `tcp_nodelay` to a
            // caller-supplied listener, so set it per accepted socket.
            let incoming = tokio_stream::wrappers::TcpListenerStream::new(listener).map(|conn| {
                conn.inspect(|sock| {
                    let _ = sock.set_nodelay(true);
                })
            });
            let serve = builder
                .add_service(svc)
                .serve_with_incoming_shutdown(incoming, deadline);
            serve.await.unwrap();
        }
        Transport::Raw => {
            let acceptor = a.tls.then(|| server_tls_acceptor(&cert_pem, &key_pem));
            loop {
                tokio::select! {
                    () = &mut deadline => break,
                    res = listener.accept() => {
                        let (sock, _) = res.unwrap();
                        sock.set_nodelay(true).ok();
                        let shared = shared.clone();
                        let acceptor = acceptor.clone();
                        tokio::spawn(async move {
                            let result = if let Some(acc) = acceptor {
                                match acc.accept(sock).await {
                                    Ok(tls) => raw_serve_conn(tls, shared).await,
                                    Err(e) => Err(e),
                                }
                            } else {
                                raw_serve_conn(sock, shared).await
                            };
                            // A clean close by the client is an EOF at a frame
                            // boundary; anything else is worth reporting.
                            // A clean close by the client is an EOF at a frame
                            // boundary; anything else is worth reporting.
                            if let Err(e) = result
                                && e.kind() != std::io::ErrorKind::UnexpectedEof
                            {
                                eprintln!("connection error: {e}");
                            }
                        });
                    }
                }
            }
        }
    }

    let seconds = start.elapsed().as_secs_f64();
    let (user, sys, rss) = rusage();
    let stats = Stats {
        role: "server",
        transport: format!("{:?}", a.transport).to_lowercase(),
        tls: a.tls,
        shard_bytes: 0,
        frame_bytes: a.frame_bytes,
        seconds,
        requests: shared.requests.load(Ordering::Relaxed),
        bytes: shared.bytes.load(Ordering::Relaxed),
        throughput_mib_s: shared.bytes.load(Ordering::Relaxed) as f64 / seconds / (1024.0 * 1024.0),
        cpu_user_s: user,
        cpu_sys_s: sys,
        cpu_percent: (user + sys) / seconds * 100.0,
        max_rss_bytes: rss,
        ..Default::default()
    };
    println!("{}", serde_json::to_string(&stats).unwrap());
}

async fn raw_serve_conn<S: AsyncRead + AsyncWrite + Unpin>(
    mut s: S,
    shared: ServerShared,
) -> std::io::Result<()> {
    let mut buf = Vec::with_capacity(shared.frame_bytes);
    loop {
        let ty = read_frame(&mut s, &mut buf).await?;
        match ty {
            F_PUT_HDR => {
                let mut crc = 0u32;
                let mut received = 0u64;
                loop {
                    let ty = read_frame(&mut s, &mut buf).await?;
                    match ty {
                        F_DATA => {
                            crc = crc32c::crc32c_append(crc, &buf);
                            received += buf.len() as u64;
                            if !shared.delay.is_zero() {
                                tokio::time::sleep(shared.delay).await;
                            }
                        }
                        F_PUT_END => break,
                        _ => return Err(std::io::Error::other("unexpected frame")),
                    }
                }
                shared.requests.fetch_add(1, Ordering::Relaxed);
                shared.bytes.fetch_add(received, Ordering::Relaxed);
                let mut ack = [0u8; 12];
                ack[..4].copy_from_slice(&crc.to_le_bytes());
                ack[4..].copy_from_slice(&received.to_le_bytes());
                write_frame(&mut s, F_PUT_ACK, &ack).await?;
                s.flush().await?;
            }
            F_GET_REQ => {
                let len = u64::from_le_bytes(buf[..8].try_into().unwrap());
                let mut sent = 0u64;
                while sent < len {
                    let n = (len - sent).min(shared.payload.len() as u64) as usize;
                    write_frame(&mut s, F_DATA, &shared.payload[..n]).await?;
                    sent += n as u64;
                    if !shared.delay.is_zero() {
                        tokio::time::sleep(shared.delay).await;
                    }
                }
                write_frame(&mut s, F_GET_END, &[]).await?;
                s.flush().await?;
                shared.requests.fetch_add(1, Ordering::Relaxed);
                shared.bytes.fetch_add(sent, Ordering::Relaxed);
            }
            _ => return Err(std::io::Error::other("unexpected frame")),
        }
    }
}

struct GrpcServer {
    shared: ServerShared,
}

#[tonic::async_trait]
impl pb::storage_node_server::StorageNode for GrpcServer {
    type GetShardStream = ReceiverStream<Result<pb::GetShardResponse, tonic::Status>>;

    async fn put_shard(
        &self,
        request: tonic::Request<tonic::Streaming<pb::PutShardRequest>>,
    ) -> Result<tonic::Response<pb::PutShardResponse>, tonic::Status> {
        let mut stream = request.into_inner();
        let mut crc = 0u32;
        let mut received = 0u64;
        while let Some(msg) = stream.next().await {
            let msg = msg?;
            match msg.body {
                Some(pb::put_shard_request::Body::Header(h)) => {
                    if h.protocol_version != pb::PROTOCOL_VERSION {
                        return Err(tonic::Status::failed_precondition("protocol version"));
                    }
                }
                Some(pb::put_shard_request::Body::Data(d)) => {
                    crc = crc32c::crc32c_append(crc, &d);
                    received += d.len() as u64;
                    if !self.shared.delay.is_zero() {
                        tokio::time::sleep(self.shared.delay).await;
                    }
                }
                None => {}
            }
        }
        self.shared.requests.fetch_add(1, Ordering::Relaxed);
        self.shared.bytes.fetch_add(received, Ordering::Relaxed);
        Ok(tonic::Response::new(pb::PutShardResponse {
            crc32c: crc,
            bytes_received: received,
            sequence: 0,
            store_epoch: 0,
        }))
    }

    async fn get_shard(
        &self,
        request: tonic::Request<pb::GetShardRequest>,
    ) -> Result<tonic::Response<Self::GetShardStream>, tonic::Status> {
        let len = request.into_inner().len;
        let (tx, rx) = tokio::sync::mpsc::channel(4);
        let shared = self.shared.clone();
        tokio::spawn(async move {
            let mut sent = 0u64;
            while sent < len {
                let n = (len - sent).min(shared.payload.len() as u64) as usize;
                if tx
                    .send(Ok(pb::GetShardResponse {
                        data: shared.payload.slice(..n),
                    }))
                    .await
                    .is_err()
                {
                    return;
                }
                sent += n as u64;
                if !shared.delay.is_zero() {
                    tokio::time::sleep(shared.delay).await;
                }
            }
            shared.requests.fetch_add(1, Ordering::Relaxed);
            shared.bytes.fetch_add(sent, Ordering::Relaxed);
        });
        Ok(tonic::Response::new(ReceiverStream::new(rx)))
    }

    // The remaining RPCs are not part of the transfer measurement.
    async fn delete_shard(
        &self,
        _request: tonic::Request<pb::DeleteShardRequest>,
    ) -> Result<tonic::Response<pb::DeleteShardResponse>, tonic::Status> {
        Err(tonic::Status::unimplemented("benchmark server"))
    }

    async fn list_shards(
        &self,
        _request: tonic::Request<pb::ListShardsRequest>,
    ) -> Result<tonic::Response<pb::ListShardsResponse>, tonic::Status> {
        Err(tonic::Status::unimplemented("benchmark server"))
    }

    async fn verify_shards(
        &self,
        _request: tonic::Request<pb::VerifyShardsRequest>,
    ) -> Result<tonic::Response<pb::VerifyShardsResponse>, tonic::Status> {
        Err(tonic::Status::unimplemented("benchmark server"))
    }

    async fn scrub_shards(
        &self,
        _request: tonic::Request<pb::ScrubShardsRequest>,
    ) -> Result<tonic::Response<pb::ScrubShardsResponse>, tonic::Status> {
        Err(tonic::Status::unimplemented("benchmark server"))
    }

    async fn update_group_epoch(
        &self,
        _request: tonic::Request<pb::UpdateGroupEpochRequest>,
    ) -> Result<tonic::Response<pb::UpdateGroupEpochResponse>, tonic::Status> {
        Err(tonic::Status::unimplemented("benchmark server"))
    }

    async fn health(
        &self,
        _request: tonic::Request<pb::HealthRequest>,
    ) -> Result<tonic::Response<pb::HealthResponse>, tonic::Status> {
        Ok(tonic::Response::new(pb::HealthResponse::default()))
    }
}

// ---------------------------------------------------------------- client

async fn run_client(a: ClientArgs) {
    let ca = if a.tls {
        Some(tokio::fs::read_to_string(&a.ca_cert).await.unwrap())
    } else {
        None
    };
    let payload = Bytes::from(vec![0xA5u8; a.frame_bytes]);
    let deadline = Instant::now() + Duration::from_secs(a.duration);
    let start = Instant::now();

    let mut tasks = Vec::new();
    match a.transport {
        Transport::Grpc => {
            let mut channels = Vec::new();
            for _ in 0..a.connections.max(1) {
                let scheme = if a.tls { "https" } else { "http" };
                let mut ep = Channel::from_shared(format!("{scheme}://{}", a.addr))
                    .unwrap()
                    .tcp_nodelay(true)
                    .initial_stream_window_size(Some(arca_lake_protocol::client::STREAM_WINDOW))
                    .initial_connection_window_size(Some(
                        arca_lake_protocol::client::CONNECTION_WINDOW,
                    ));
                if let Some(ca) = &ca {
                    ep = ep
                        .tls_config(
                            ClientTlsConfig::new()
                                .ca_certificate(Certificate::from_pem(ca))
                                .domain_name("localhost"),
                        )
                        .unwrap();
                }
                channels.push(ep.connect().await.unwrap());
            }
            for i in 0..a.concurrency {
                let ch = channels[i % channels.len()].clone();
                let payload = payload.clone();
                let (op, shard, frame) = (a.op, a.shard_bytes, a.frame_bytes);
                tasks.push(tokio::spawn(async move {
                    let mut client = pb::storage_node_client::StorageNodeClient::new(ch)
                        .max_decoding_message_size(64 << 20);
                    let mut lat = Vec::new();
                    let mut bytes = 0u64;
                    while Instant::now() < deadline {
                        let t = Instant::now();
                        match op {
                            Op::Put => {
                                let (tx, rx) = tokio::sync::mpsc::channel(4);
                                let payload = payload.clone();
                                tokio::spawn(async move {
                                    let header = pb::PutShardRequest {
                                        body: Some(pb::put_shard_request::Body::Header(
                                            pb::PutShardHeader {
                                                protocol_version: pb::PROTOCOL_VERSION,
                                                key: Some(pb::ShardKey {
                                                    group_id: 1,
                                                    chunk_id: Bytes::from_static(&[0; 16]),
                                                    shard_index: 0,
                                                }),
                                                group_epoch: 1,
                                                payload_len: shard as u64,
                                            },
                                        )),
                                    };
                                    if tx.send(header).await.is_err() {
                                        return;
                                    }
                                    let mut sent = 0;
                                    while sent < shard {
                                        let n = (shard - sent).min(frame);
                                        let msg = pb::PutShardRequest {
                                            body: Some(pb::put_shard_request::Body::Data(
                                                payload.slice(..n),
                                            )),
                                        };
                                        if tx.send(msg).await.is_err() {
                                            return;
                                        }
                                        sent += n;
                                    }
                                });
                                let resp = client
                                    .put_shard(ReceiverStream::new(rx))
                                    .await
                                    .unwrap()
                                    .into_inner();
                                assert_eq!(resp.bytes_received, shard as u64);
                                bytes += shard as u64;
                            }
                            Op::Get => {
                                let req = pb::GetShardRequest {
                                    protocol_version: pb::PROTOCOL_VERSION,
                                    key: Some(pb::ShardKey {
                                        group_id: 1,
                                        chunk_id: Bytes::from_static(&[0; 16]),
                                        shard_index: 0,
                                    }),
                                    offset: 0,
                                    len: shard as u64,
                                };
                                let mut stream = client.get_shard(req).await.unwrap().into_inner();
                                let mut got = 0u64;
                                while let Some(m) = stream.next().await {
                                    got += m.unwrap().data.len() as u64;
                                }
                                assert_eq!(got, shard as u64);
                                bytes += got;
                            }
                        }
                        lat.push(t.elapsed().as_secs_f64() * 1e3);
                    }
                    (lat, bytes)
                }));
            }
        }
        Transport::Raw => {
            let connector = ca.as_deref().map(client_tls_connector);
            for _ in 0..a.concurrency {
                let payload = payload.clone();
                let (op, shard, frame, addr) = (a.op, a.shard_bytes, a.frame_bytes, a.addr);
                let connector = connector.clone();
                tasks.push(tokio::spawn(async move {
                    let sock = TcpStream::connect(addr).await.unwrap();
                    sock.set_nodelay(true).ok();
                    if let Some(c) = connector {
                        let name = rustls::pki_types::ServerName::try_from("localhost").unwrap();
                        let tls = c.connect(name, sock).await.unwrap();
                        raw_client_loop(tls, op, shard, frame, payload, deadline).await
                    } else {
                        raw_client_loop(sock, op, shard, frame, payload, deadline).await
                    }
                }));
            }
        }
    }

    let mut lat = Vec::new();
    let mut bytes = 0u64;
    for t in tasks {
        let (l, b) = t.await.unwrap();
        lat.extend(l);
        bytes += b;
    }
    let seconds = start.elapsed().as_secs_f64();
    lat.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let (user, sys, rss) = rusage();
    let stats = Stats {
        role: "client",
        label: a.label,
        transport: format!("{:?}", a.transport).to_lowercase(),
        tls: a.tls,
        op: format!("{:?}", a.op).to_lowercase(),
        shard_bytes: a.shard_bytes,
        frame_bytes: a.frame_bytes,
        concurrency: a.concurrency,
        seconds,
        requests: lat.len() as u64,
        bytes,
        throughput_mib_s: bytes as f64 / seconds / (1024.0 * 1024.0),
        latency_p50_ms: percentile(&lat, 0.5),
        latency_p99_ms: percentile(&lat, 0.99),
        cpu_user_s: user,
        cpu_sys_s: sys,
        cpu_percent: (user + sys) / seconds * 100.0,
        max_rss_bytes: rss,
    };
    println!("{}", serde_json::to_string(&stats).unwrap());
}

async fn raw_client_loop<S: AsyncRead + AsyncWrite + Unpin>(
    mut s: S,
    op: Op,
    shard: usize,
    frame: usize,
    payload: Bytes,
    deadline: Instant,
) -> (Vec<f64>, u64) {
    let mut lat = Vec::new();
    let mut bytes = 0u64;
    let mut buf = Vec::with_capacity(frame);
    while Instant::now() < deadline {
        let t = Instant::now();
        match op {
            Op::Put => {
                let mut hdr = [0u8; 8];
                hdr.copy_from_slice(&(shard as u64).to_le_bytes());
                write_frame(&mut s, F_PUT_HDR, &hdr).await.unwrap();
                let mut sent = 0;
                while sent < shard {
                    let n = (shard - sent).min(frame);
                    write_frame(&mut s, F_DATA, &payload[..n]).await.unwrap();
                    sent += n;
                }
                write_frame(&mut s, F_PUT_END, &[]).await.unwrap();
                s.flush().await.unwrap();
                let ty = match read_frame(&mut s, &mut buf).await {
                    Ok(ty) => ty,
                    Err(e) => panic!("after {} requests: ack read failed: {e}", lat.len()),
                };
                assert_eq!(ty, F_PUT_ACK);
                bytes += shard as u64;
            }
            Op::Get => {
                write_frame(&mut s, F_GET_REQ, &(shard as u64).to_le_bytes())
                    .await
                    .unwrap();
                s.flush().await.unwrap();
                let mut got = 0u64;
                loop {
                    let ty = read_frame(&mut s, &mut buf).await.unwrap();
                    match ty {
                        F_DATA => got += buf.len() as u64,
                        F_GET_END => break,
                        _ => panic!("unexpected frame"),
                    }
                }
                assert_eq!(got, shard as u64);
                bytes += got;
            }
        }
        lat.push(t.elapsed().as_secs_f64() * 1e3);
    }
    (lat, bytes)
}
